CREATE TABLE IF NOT EXISTS clin_patients ( id INTEGER PRIMARY KEY AUTOINCREMENT, reg_no TEXT, division TEXT NOT NULL, name TEXT NOT NULL, phone TEXT, sex TEXT, dob TEXT, age_years INTEGER, file_no TEXT, clinic_id INTEGER, diagnosis TEXT NOT NULL, diagnosis_detail TEXT, ear TEXT, degree TEXT, stage TEXT NOT NULL, priority TEXT NOT NULL DEFAULT 'routine', next_review TEXT, referred_by TEXT, clinician TEXT, notes TEXT, status TEXT NOT NULL DEFAULT 'active', created_by INTEGER, created_by_name TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_clin_patients_division ON clin_patients(division, status, next_review); CREATE INDEX IF NOT EXISTS idx_clin_patients_phone ON clin_patients(phone); CREATE TABLE IF NOT EXISTS clin_entries ( id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL REFERENCES clin_patients(id) ON DELETE CASCADE, kind TEXT NOT NULL, title TEXT, body TEXT, stage_from TEXT, stage_to TEXT, entry_date TEXT NOT NULL, created_by INTEGER, created_by_name TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_clin_entries_patient ON clin_entries(patient_id, entry_date);
